import * as T from './vendor/three.module.min.js';
const textures={};
export async function initializeSpringTextures(decode){await Promise.all(['limestone-strata','limestone-flowstone','mineral-poolbed','spring-ripples'].map(async name=>{const url=new URL('./textures/level27/'+name+'.webp',import.meta.url);let t;if(decode){const image=await decode(url,512,512);t=new T.DataTexture(image.data,image.width,image.height);t.flipY=true;t.needsUpdate=true;}else t=await new T.TextureLoader().loadAsync(url.href);t.wrapS=t.wrapT=T.RepeatWrapping;t.minFilter=T.LinearMipmapLinearFilter;t.magFilter=T.LinearFilter;t.generateMipmaps=true;t.colorSpace=name==='spring-ripples'?T.NoColorSpace:T.SRGBColorSpace;t.anisotropy=4;textures[name]=t;}));}
export function springTextures(){return textures;}
export function springMaterials(){const material=(name,color,roughness=.78)=>new T.MeshStandardMaterial({name:'Level 27 / '+name,map:textures[name],bumpMap:textures[name],bumpScale:.028,color,roughness,side:T.DoubleSide});return{rock:material('limestone-strata',0x96918a),calcite:material('limestone-flowstone',0xb7b2a2,.62),bed:material('mineral-poolbed',0x939183,.68),metal:new T.MeshStandardMaterial({color:0x7f9691,metalness:.7,roughness:.38}),concrete:new T.MeshStandardMaterial({map:textures['mineral-poolbed'],color:0x999b91,roughness:.92}),black:new T.MeshStandardMaterial({color:0x101310,roughness:.9}),lamp:new T.MeshBasicMaterial({color:0xffdfa2})};}
